$path = 'admin-panel/app/islamic-lifestyle/page.tsx'
$text = Get-Content -Raw $path

$text = $text.Replace('import ReactMarkdown from "react-markdown";' + "`r`n", '')
$text = $text.Replace('const editorRef=useRef<HTMLTextAreaElement>(null),imageInputRef=useRef<HTMLInputElement>(null);', 'const editorRef=useRef<HTMLDivElement>(null),imageInputRef=useRef<HTMLInputElement>(null);')
$text = $text.Replace('const[preview,setPreview]=useState(false),[markdownHelp,setMarkdownHelp]=useState(false),[imageUploading,setImageUploading]=useState(false);', 'const[imageUploading,setImageUploading]=useState(false);')

$oldFunctions = '(?s)const format=\(before:string.*?\r?\nconst uploadEditorImage=.*?\r?\n const categories='
$newFunctions = @'
const syncEditor=()=>setForm(current=>({...current,content:editorRef.current?.innerHTML||""}));
 const command=(name:string,value?:string)=>{editorRef.current?.focus();document.execCommand(name,false,value);syncEditor()};
 const addLink=()=>{const url=window.prompt("Enter the complete link (https://...)");if(url)command("createLink",url)};
 const uploadEditorImage=async(file:File|null)=>{if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)){setMessage("Choose a JPG, PNG or WebP image.");return}if(file.size>8*1024*1024){setMessage("Image must be 8 MB or smaller.");return}setImageUploading(true);setMessage("");try{const response=await fetch(API+"/api/admin/books/cover-upload",{method:"POST",headers:headers(),body:JSON.stringify({fileName:file.name,contentType:file.type})}),payload=await response.json();if(!response.ok)throw Error(payload.message||"Unable to prepare image upload.");const uploaded=await fetch(payload.data.uploadUrl,{method:"PUT",headers:{"Content-Type":payload.data.contentType},body:file});if(!uploaded.ok)throw Error("Image upload failed.");command("insertImage",payload.data.publicUrl);setMessage("Image uploaded and inserted into the chapter.")}catch(error){setMessage(error instanceof Error?error.message:"Unable to upload image.")}finally{setImageUploading(false);if(imageInputRef.current)imageInputRef.current.value=""}};
 const categories=
'@
$text = [regex]::Replace($text, $oldFunctions, $newFunctions)

$oldEditor = '(?s)<div className="markdownToolbar".*?</label>\}'
$newEditor = @'
<div className="markdownToolbar" role="toolbar" aria-label="Rich text formatting" onMouseDown={event=>event.preventDefault()}><button type="button" title="Bold (Ctrl+B)" onClick={()=>command("bold")}><b>B</b><span>Bold</span></button><button type="button" title="Italic (Ctrl+I)" onClick={()=>command("italic")}><em>I</em><span>Italic</span></button><button type="button" title="Large heading" onClick={()=>command("formatBlock","H2")}><b>H2</b><span>Heading</span></button><button type="button" title="Small heading" onClick={()=>command("formatBlock","H3")}><b>H3</b><span>Subheading</span></button><button type="button" title="Quote" onClick={()=>command("formatBlock","BLOCKQUOTE")}><b>&gt;</b><span>Quote</span></button><button type="button" title="Bullet list" onClick={()=>command("insertUnorderedList")}><b>•</b><span>Bullets</span></button><button type="button" title="Numbered list" onClick={()=>command("insertOrderedList")}><b>1.</b><span>Numbers</span></button><button type="button" title="Add link" onClick={addLink}><b>@</b><span>Link</span></button><button type="button" title="Remove formatting" onClick={()=>command("removeFormat")}><b>Tx</b><span>Clear</span></button><button type="button" title="Upload JPG, PNG or WebP" disabled={imageUploading} onClick={()=>imageInputRef.current?.click()}><b>IMG</b><span>{imageUploading?"Uploading...":"Image"}</span></button></div><input ref={imageInputRef} className="hiddenImageInput" type="file" accept="image/jpeg,image/png,image/webp" onChange={event=>void uploadEditorImage(event.target.files?.[0]||null)}/><div ref={editorRef} className="richEditor" contentEditable suppressContentEditableWarning data-placeholder="Write or paste the complete Islamic chapter here..." dangerouslySetInnerHTML={{__html:form.content}} onInput={syncEditor} onKeyDown={event=>{if(!(event.ctrlKey||event.metaKey))return;if(event.key.toLowerCase()==="b"){event.preventDefault();command("bold")}else if(event.key.toLowerCase()==="i"){event.preventDefault();command("italic")}}}/><em>{form.content.replace(/<[^>]*>/g,"").length.toLocaleString()} characters ready</em></label>}
'@
$text = [regex]::Replace($text, $oldEditor, $newEditor, 1)

$text = $text.Replace('.contentUpload textarea{min-height:440px;font:14px/1.7 Georgia,serif}', '.richEditor{min-height:440px;padding:20px;border:1px solid #cfddd3;border-radius:0 0 11px 11px;background:#fff;color:#203f31;font:16px/1.75 Arial,sans-serif;outline:none;overflow:auto}.richEditor:focus{border-color:#087a4d;box-shadow:0 0 0 3px #087a4d18}.richEditor:empty:before{content:attr(data-placeholder);color:#8a9890}.richEditor h1{font-size:32px}.richEditor h2{font-size:26px}.richEditor h3{font-size:21px}.richEditor h1,.richEditor h2,.richEditor h3{margin:20px 0 10px;color:#075b3b;line-height:1.3}.richEditor p{margin:9px 0}.richEditor blockquote{margin:14px 0;padding:12px 16px;border-left:4px solid #b89536;border-radius:0 9px 9px 0;background:#fff8df;color:#4e472e}.richEditor ul,.richEditor ol{padding-left:26px}.richEditor li{margin:7px 0}.richEditor a{color:#087a4d;text-decoration:underline}.richEditor img{display:block;max-width:100%;height:auto;margin:16px auto;border-radius:12px;box-shadow:0 4px 14px #173d2e22}')

Set-Content -Path $path -Value $text -Encoding utf8
